              bit_14 = 1'b0;
            end
            3'h4: begin
              bit_14 = 1'b1;
              case (mant_lo4)
                4'h0: bit_14 = 1'b0;
                4'h1: bit_14 = 1'b0;
                4'h2: bit_14 = 1'b0;
                4'h3: bit_14 = 1'b0;
                4'h4: bit_14 = 1'b0;
                4'h5: bit_14 = 1'b0;
                4'h6: bit_14 = 1'b0;
                default: begin end
              endcase
            end
            3'h5: begin
              bit_14 = 1'b1;
            end
            3'h6: begin
              bit_14 = 1'b1;
            end
            3'h7: begin
              bit_14 = 1'b1;
            end
            default: begin end
          endcase
        end
      default: begin end
    endcase
  end
  reg bit_15;
  always @* begin
    bit_15 = 1'b0;
    casez (sign_exp)
      9'b000??????: bit_15 = 1'b1;
      9'b0010?????: bit_15 = 1'b1;
      9'b00110????: bit_15 = 1'b1;
      9'b001110???: bit_15 = 1'b1;
      9'b0011110??: bit_15 = 1'b1;
